int def scoreLate(int:lateCount) {
    int score = lateCount * 5;
    if (score > 25) {
        score = 25;
    }
    return score;
}


int def scoreMissingInvoice(int:missingInvoice) {
    int score = missingInvoice * 8;
    if (score > 24) {
        score = 24;
    }
    return score;
}


int def scoreBurden(double:taxBurdenRate, double:industryAvgBurden) {
    if (taxBurdenRate < industryAvgBurden * 0.5) {
        return 20;
    } else if (taxBurdenRate < industryAvgBurden * 0.8) {
        return 12;
    } else {
        return 0;
    }
}


int def scoreInputRatio(double:inputTaxRatio) {
    if (inputTaxRatio > 0.95) {
        return 15;
    } else if (inputTaxRatio > 0.85) {
        return 8;
    } else {
        return 0;
    }
}


int def scoreAbnormal(boolean:hasAbnormalInvoice) {
    if (hasAbnormalInvoice) {
        return 20;
    } else {
        return 0;
    }
}


int def scoreAge(int:yearsSinceRegister) {
    if (yearsSinceRegister < 1) {
        return 10;
    } else if (yearsSinceRegister < 3) {
        return 5;
    } else {
        return 0;
    }
}


str def riskLevel(int:riskScore) {
    if (riskScore >= 70) {
        return "HIGH";
    } else if (riskScore >= 40) {
        return "MEDIUM";
    } else {
        return "LOW";
    }
}


str def auditLevel(int:riskScore, boolean:hasAbnormalInvoice) {
    if (hasAbnormalInvoice) {
        return "TAX_AUDIT";
    } else if (riskScore >= 70) {
        return "TAX_AUDIT";
    } else if (riskScore >= 40) {
        return "FIELD_VISIT";
    } else {
        return "SELF_CHECK";
    }
}


boolean def needWarning(int:riskScore) {
    if (riskScore >= 40) {
        return true;
    } else {
        return false;
    }
}


boolean def needInvestigation(int:riskScore, boolean:hasAbnormalInvoice) {
    if (hasAbnormalInvoice) {
        return true;
    } else if (riskScore >= 70) {
        return true;
    } else {
        return false;
    }
}
